[CmdletBinding()]
param([Parameter(Position=0)][string]$InputPath,[switch]$Recursive,[double]$ThresholdDb=-60,[double]$MinSilence=0.10,[Nullable[double]]$MaxLeading,[Nullable[double]]$MaxTrailing,[switch]$Json,[string]$Output,[switch]$Help)
. "$PSScriptRoot/lib/Common.ps1"
if($Help){'batchsilence BETA - compare leading/trailing silence across a batch';'Usage: .\batchsilence.ps1 DIR [-ThresholdDb DB] [-MinSilence SEC] [-MaxLeading SEC] [-MaxTrailing SEC] [-Recursive] [-Json]';exit 0};if(-not $InputPath){[Console]::Error.WriteLine('directory required');exit 2};Assert-CDLDependencies
try{$files=@(Get-CDLAudioFiles $InputPath -Recursive:$Recursive)}catch{[Console]::Error.WriteLine($_.Exception.Message);exit 2};if(-not $files.Count){[Console]::Error.WriteLine('no supported audio files');exit 2}
$rows=@();$find=@();$inv=[Globalization.CultureInfo]::InvariantCulture
foreach($f in $files){$durText=Get-CDLProbeValue $f duration format;$dur=if($durText){[double]::Parse($durText,$inv)}else{0};$lines=& ffmpeg -hide_banner -nostats -i $f -af "silencedetect=noise=$($ThresholdDb.ToString($inv))dB:d=$($MinSilence.ToString($inv))" -f null - 2>&1;$starts=@();$ends=@();foreach($line in $lines){$s="$line";if($s -match 'silence_start:\s*([-0-9.]+)'){$starts += [double]::Parse($Matches[1],$inv)};if($s -match 'silence_end:\s*([-0-9.]+)'){$ends += [double]::Parse($Matches[1],$inv)}};$lead=0.0;if($starts.Count -and $starts[0] -le 0.0001 -and $ends.Count){$lead=$ends[0]};$trail=0.0;if($starts.Count){$ls=$starts[-1];$le=if($ends.Count){$ends[-1]}else{$null};if($null -eq $le -or [math]::Abs($dur-$le)-lt 0.02){$trail=[math]::Max(0,$dur-$ls)}};$rows+=[pscustomobject][ordered]@{path=$f;duration_seconds=$dur;leading_silence_seconds=$lead;trailing_silence_seconds=$trail;leading_ratio=if($dur){$lead/$dur}else{0};trailing_ratio=if($dur){$trail/$dur}else{0}};if($null -ne $MaxLeading -and $lead -gt $MaxLeading){$find+=New-CDLFinding 'excessive_leading_silence' "leading silence $lead exceeds $MaxLeading" $f};if($null -ne $MaxTrailing -and $trail -gt $MaxTrailing){$find+=New-CDLFinding 'excessive_trailing_silence' "trailing silence $trail exceeds $MaxTrailing" $f}}
$status=if($find.Count){'review'}else{'ok'};$report=[ordered]@{tool='batchsilence';version=$script:CDLVersion;generated_utc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');inputs=@($InputPath);dependencies=Get-CDLVersions;options=[ordered]@{threshold_db=$ThresholdDb;min_silence=$MinSilence};measurements=[ordered]@{files=$rows};findings=$find;status=$status};Write-CDLReport $report -Json:$Json -Output $Output -Text "batchsilence BETA: $($rows.Count) files status=$status";if($find.Count){exit 1};exit 0
